mapper.select:
SELECT ra.id, ra.create_time, ra.member_username, ra.product_real_price, ra.product_count, ra.return_name, ra.status, ra.handle_time FROM oms_order_return_apply ra JOIN oms_order o ON ra.order_id = o.id WHERE 1 = 1
AND o.shop_id = #{shopId}
AND ra.id = #{queryParam.id}
AND ra.status = #{queryParam.status}
AND ra.handle_man = #{queryParam.handleMan}
AND ra.create_time LIKE CONCAT(#{queryParam.createTime}, '%')
AND ra.handle_time LIKE CONCAT(#{queryParam.handleTime}, '%')
AND (ra.return_name LIKE concat("%",#{queryParam.receiverKeyword},"%") OR ra.return_phone LIKE concat("%",#{queryParam.receiverKeyword},"%"))
